package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.common.iteration.CloseableIteration;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.junit.jupiter.api.Test;

/** A first-output expectation does not bound how many input rows a filter might reject first. */
class LmdbNativeFilteredDemandQuoteTest {

	private static final int INPUT_ROWS = 100;

	@Test
	void aLastRowMatchKeepsTheCompleteInputWorkInsideItsSlicedCeiling() throws Exception {
		Measured late = execute(INPUT_ROWS, 1L);
		assertThat(late.predicateCalls()).as("the first output follows ninety-nine rejected input rows")
				.isEqualTo(INPUT_ROWS);
		assertThat(late.outputRows()).isEqualTo(1);
		LmdbNativeCostVector sliced = late.selected().features();
		double complete = late.fullQuote().total().high(Feature.INTERPRETED_ROW);
		assertThat(sliced.expected(Feature.INTERPRETED_ROW))
				.as("an expected fraction is allowed; it is not an upper bound on the late first match")
				.isBetween(0D, complete);
		assertThat(sliced.high(Feature.INTERPRETED_ROW))
				.as("all %s real predicate calls and their input pulls happened before LIMIT 1; expected=%s",
						late.predicateCalls(), sliced.expected(Feature.INTERPRETED_ROW))
				.isGreaterThanOrEqualTo(complete);
	}

	@Test
	void aFirstRowMatchCanStillReceiveAStreamingExpectation() throws Exception {
		Measured early = execute(1, 1L);
		assertThat(early.predicateCalls()).isEqualTo(1);
		assertThat(early.outputRows()).isEqualTo(1);
		double oneRow = early.fullQuote().total().expected(Feature.INTERPRETED_ROW) * (1D / INPUT_ROWS);
		assertThat(early.selected().features().expected(Feature.INTERPRETED_ROW)).isEqualTo(oneRow);
		assertThat(early.selected().features().high(Feature.INTERPRETED_ROW)).isGreaterThanOrEqualTo(oneRow);
	}

	@Test
	void uniformlyAcceptedInputStillStopsAndPricesItsExpectedFraction() throws Exception {
		Measured uniform = execute(0, 1L);
		assertThat(uniform.predicateCalls()).isEqualTo(1);
		assertThat(uniform.outputRows()).isEqualTo(1);
		double oneRow = uniform.fullQuote().total().expected(Feature.INTERPRETED_ROW) * (1D / INPUT_ROWS);
		assertThat(uniform.selected().features().expected(Feature.INTERPRETED_ROW)).isEqualTo(oneRow);
		assertThat(uniform.selected().features().high(Feature.INTERPRETED_ROW)).isGreaterThanOrEqualTo(oneRow);
	}

	@Test
	void anUnslicedFilterKeepsItsCompleteWorkQuote() throws Exception {
		Measured full = execute(INPUT_ROWS, -1L);
		assertThat(full.predicateCalls()).isEqualTo(INPUT_ROWS);
		assertThat(full.outputRows()).isEqualTo(1);
		assertThat(full.selected().features().expected(Feature.INTERPRETED_ROW))
				.isEqualTo(full.fullQuote().total().expected(Feature.INTERPRETED_ROW));
		assertThat(full.selected().features().high(Feature.INTERPRETED_ROW))
				.isEqualTo(full.fullQuote().total().high(Feature.INTERPRETED_ROW));
	}

	@Test
	void theLateFirstMatchCannotClaimStrictIntervalDominanceOverABlockingRival() throws Exception {
		Measured late = execute(INPUT_ROWS, 1L);
		LmdbNativeCandidate<String> streaming = LmdbNativeCandidate.of("filtered",
				LmdbNativeCostQuote.streaming(late.selected().features(), 1D), () -> "filtered");
		LmdbNativeCandidate<String> blocking = LmdbNativeCandidate.of("blocking",
				new LmdbNativeCostQuote(LmdbNativeCostVector.point(Feature.INTERPRETED_ROW, 10D),
						LmdbNativeCostVector.zero(), 1D, false, false),
				() -> "blocking");
		LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(List.of(streaming, blocking),
				LmdbNativeStaticPrior.DEFAULT, 1D, 4);
		assertThat(late.predicateCalls()).isEqualTo(INPUT_ROWS);
		assertThat(ranking.eliminatedBy()[1])
				.as("a low expected first-match cost cannot prove its whole interval is below a blocking rival")
				.isNull();
	}

	private record Measured(int predicateCalls, int outputRows, LmdbNativeCostQuote fullQuote,
			LmdbNativeDecisionRecord.Entry selected) {
	}

	/** Zero accepts every row; a positive value accepts only that one-based input ordinal. */
	private static Measured execute(int acceptedOrdinal, long limit) throws Exception {
		LmdbNativeRowDetachmentTest.FakeStoreSource source = new LmdbNativeRowDetachmentTest.FakeStoreSource();
		long key = source.add(SimpleValueFactory.getInstance().createIRI("urn:filtered-demand:key"));
		LinkedHashMap<String, Integer> names = new LinkedHashMap<>();
		names.put("key", 0);
		NativeSlotLayout layout = new NativeSlotLayout(names, null);
		layout.freeze(List.of("key"));
		ValuesRow[] rows = new ValuesRow[INPUT_ROWS];
		for (int i = 0; i < rows.length; i++) {
			rows[i] = new ValuesRow(new int[] { 0 }, new long[] { key });
		}
		AtomicInteger predicateCalls = new AtomicInteger();
		SlotPlan plan = new FilterPlan(new ValuesPlan(rows), row -> {
			int ordinal = predicateCalls.incrementAndGet();
			return acceptedOrdinal == 0 || ordinal == acceptedOrdinal;
		}, -1L);
		LmdbNativeEvaluationStrategy strategy = mock(LmdbNativeEvaluationStrategy.class);
		when(strategy.forcedExecutionStrategyName()).thenReturn(LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
		NativeRowsStep step = new NativeRowsStep(source, plan, layout, new int[] { 0 }, new String[] { "key" },
				false, new int[0], new boolean[0], 0L, limit, false, strategy, null, null, Set.of(), null, null);
		LmdbNativeCostQuote fullQuote;
		RowState quotingRow = new RowState(source, layout, EmptyBindingSet.getInstance());
		try {
			fullQuote = LmdbNativeCostQuote.streaming(LmdbNativePlanExecutionProfile.profile(plan, quotingRow, 0L,
					LmdbNativePlanExecutionProfile.Mode.SEQUENTIAL), INPUT_ROWS);
		} finally {
			quotingRow.memoryScope.close();
		}
		List<LmdbNativeDecisionRecord.Entry> selected = new ArrayList<>();
		LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
			assertThat(id).isEqualTo(LmdbNativeAttemptMetrics.PATH_NESTED_LOOP);
			selected.add(record.entries().get(record.winner()));
		});
		int outputRows = 0;
		try (CloseableIteration<BindingSet> result = new NativeRowsIteration(step, source,
				EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				assertThat(result.next().getValue("key")).isEqualTo(source.lazyValue(key));
				outputRows++;
			}
		} finally {
			LmdbNativeDispatchLoop.observeSelections(null);
		}
		assertThat(selected).as("capture the post-slice quote of the successfully opened candidate").hasSize(1);
		assertThat(selected.get(0).features()).isNotNull();
		return new Measured(predicateCalls.get(), outputRows, fullQuote, selected.get(0));
	}
}
